cd /workspace && python3 - <<'EOF'
import json, sys
# 4300-digit behaviour with the C scanner
big = '1'*4301
try:
    v=json.loads('{"a": '+big+'}')
    print('big int accepted?', sys.int_info.default_max_str_digits)
except Exception as e:
    print('big int rejected:', type(e).__name__, e)
try:
    v=json.loads('{"a": '+'1'*4300+'}')
    print('4300 digits accepted')
except Exception as e:
    print('4300 rejected', e)
print(json.loads(b'{"a": 1e-400}'.decode()))
try: print(json.loads('{"a": 1e400}'))
except Exception as e: print('overflow rejected', type(e).__name__)
try: print(json.loads('{"a"\x0c: 1}'))
except Exception as e: print('form feed outside string rejected', type(e).__name__)
try: print(json.loads('{"a": 1}\x0c'))
except Exception as e: print('trailing ff rejected', type(e).__name__)
try: print(json.loads('{"a": "\v"}'))
except Exception as e: print('vertical tab in string rejected', type(e).__name__)
print(json.loads('{"a": 1}  \t\r\n'))
try: print(json.loads('{"a": 1} {"b":2}'))
except Exception as e: print('trailing json rejected', type(e).__name__)
EOF
